# Check if sieve/factor have any undocumented behavior differences
import sys
sys.path.insert(0, '.')
from more_itertools.recipes import sieve, factor

# Test with boolean inputs (True == 1, False == 0)
print("=== Boolean inputs ===")
for val in [True, False]:
    for func_name, func in [('sieve', sieve), ('factor', factor)]:
        try:
            result = list(func(val))
            print(f"  {func_name}({val}) = {result}")
        except Exception as e:
            print(f"  {func_name}({val}) raised {type(e).__name__}: {e}")

# Test with string inputs
print("\n=== String inputs ===")
for val in ["", "5", "abc"]:
    for func_name, func in [('sieve', sieve), ('factor', factor)]:
        try:
            result = list(func(val))
            print(f"  {func_name}({val!r}) = {result}")
        except Exception as e:
            print(f"  {func_name}({val!r}) raised {type(e).__name__}: {e}")

# Test with tuple/list inputs
print("\n=== Tuple/List inputs ===")
for val in [(10,), [10]]:
    for func_name, func in [('sieve', sieve), ('factor', factor)]:
        try:
